  normalized_event_title: item.normalized_event_title,
  category: item.category,
  institution: item.institution,
  geography: item.geography,
  event_date: item.event_date,
  publication_date: item.publication_date,
  first_detected: item.first_detected,
  last_updated: item.last_updated,
  briefing_file_references: item.briefing_refs,
  primary_source_ids: item.primary_source_ids,
  primary_source_urls: sourceUrlById(item.primary_source_ids),
  corroborating_source_ids: item.corroborating_source_ids,
  corroborating_source_urls: sourceUrlById(item.corroborating_source_ids),
  status: item.status_stage,
  verified_facts: item.verified_facts,
  source_claims: item.source_claims,
  what_changed: item.what_changed,
  significance: item.significance,
